  const cD_l = fD_l | EDGE_L, cD_h = fD_h | EDGE_H;
  const cA_l = fA_l | EDGE_L, cA_h = fA_h | EDGE_H;
  let sl = pl & cH_l & cV_l & cD_l & cA_l, sh = ph & cH_h & cV_h & cD_h & cA_h;
  // lan dần: quân có hàng xóm ổn định cùng màu ở một phía của mỗi trục
  for (let it = 0; it < 12; it++) {
    const h1l = ((sl << 1) & NOT_A) | (((sl >>> 1) | (sh << 31)) & NOT_H), h1h = (((sh << 1) | (sl >>> 31)) & NOT_A) | ((sh >>> 1) & NOT_H);
    const v1l = (sl << 8) | ((sl >>> 8) | (sh << 24)), v1h = ((sh << 8) | (sl >>> 24)) | (sh >>> 8);
    const d1l = ((sl << 9) & NOT_A) | (((sl >>> 9) | (sh << 23)) & NOT_H), d1h = (((sh << 9) | (sl >>> 23)) & NOT_A) | ((sh >>> 9) & NOT_H);
    const a1l = ((sl << 7) & NOT_H) | (((sl >>> 7) | (sh << 25)) & NOT_A), a1h = (((sh << 7) | (sl >>> 25)) & NOT_H) | ((sh >>> 7) & NOT_A);
    const nl = sl | (pl & (cH_l | h1l) & (cV_l | v1l) & (cD_l | d1l) & (cA_l | a1l));
    const nh = sh | (ph & (cH_h | h1h) & (cV_h | v1h) & (cD_h | d1h) & (cA_h | a1h));
    if (nl === sl && nh === sh) break;
    sl = nl; sh = nh;
  }
