      let sc = scoreAll(pl, ph, ol, oh, moves, L.depth);
      if (aborted) sc = moves.map(m => SQV[m]);           // hết giờ (máy chậm): dùng bảng điểm ô
      let best = moves[0], top = -Infinity;
      for (let i = 0; i < moves.length; i++) { const v = sc[i] + (rand() - 0.5) * 2 * L.noise; if (v > top) { top = v; best = moves[i]; } }
